import styles from "./index.module.scss";

const StatusIcon = () => {
  return (
    <svg
      width="12"
      height="18"
      viewBox="0 0 12 18"
      xmlns="http://www.w3.org/2000/svg"
    >
      <path d="M6 9C6 10.6569 4.65685 12 3 12C1.34315 12 0 10.6569 0 9C0 7.34315 1.34315 6 3 6C4.65685 6 6 7.34315 6 9Z" />
    </svg>
  );
};

const TrendingIcon = () => {
  return (
    <svg
      width="16"
      height="16"
      viewBox="0 0 16 16"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
    >
      <path
        opacity="0.4"
        d="M11.18 12.6532H4.82C4.54 12.6532 4.28667 12.4732 4.19333 12.2132L1.42 4.44653C1.2 3.82653 1.90667 3.29986 2.43333 3.67986L5.1 5.58653C5.45333 5.83986 5.96 5.68653 6.11333 5.27986L7.37333 1.91986C7.58667 1.33986 8.40667 1.33986 8.62 1.91986L9.88 5.27986C10.0333 5.6932 10.5333 5.83986 10.8933 5.58653L13.56 3.67986C14.0933 3.29986 14.7933 3.8332 14.5733 4.44653L11.8 12.2132C11.7133 12.4732 11.46 12.6532 11.18 12.6532Z"
        fill="#FF9500"
      />
      <path
        d="M11.3333 14.6665H4.66667C4.39333 14.6665 4.16667 14.4398 4.16667 14.1665C4.16667 13.8932 4.39333 13.6665 4.66667 13.6665H11.3333C11.6067 13.6665 11.8333 13.8932 11.8333 14.1665C11.8333 14.4398 11.6067 14.6665 11.3333 14.6665Z"
        fill="#FF9500"
      />
      <path
        d="M9.66667 9.8335H6.33333C6.06 9.8335 5.83333 9.60683 5.83333 9.3335C5.83333 9.06016 6.06 8.8335 6.33333 8.8335H9.66667C9.94 8.8335 10.1667 9.06016 10.1667 9.3335C10.1667 9.60683 9.94 9.8335 9.66667 9.8335Z"
        fill="#FF9500"
      />
    </svg>
  );
};

export default function WorkFlowStatus({ status }) {
  const colors = {
    inProgress: "#007AFF",
    inTesting: "#FF9500",
    finished: "#34C759",
    comingSoon: "#8E8E93",
  };

  const inPrgress = {
    borderColor: colors.inProgress,
    color: colors.inProgress,
    fill: colors.inProgress,
  };
  const inTesting = {
    borderColor: colors.inTesting,
    color: colors.inTesting,
    fill: colors.inTesting,
  };
  const finished = {
    borderColor: colors.finished,
    color: colors.finished,
    fill: colors.finished,
  };
  const comingSoon = {
    borderColor: colors.comingSoon,
    color: colors.comingSoon,
    fill: colors.comingSoon,
  };

  return (
    <div className={`${styles.flowBadge}`}>
      {(() => {
        switch (status) {
          case "In Progress":
            return (
              <span style={inPrgress}>
                <StatusIcon /> {status}
              </span>
            );
          case "Trending":
            return (
              <span style={inTesting}>
                <TrendingIcon /> {status}
              </span>
            );
          case "Finished":
            return (
              <span style={finished}>
                <StatusIcon /> {status}
              </span>
            );
          case "Coming Soon":
            return (
              <span style={comingSoon}>
                <StatusIcon /> {status}
              </span>
            );
          default:
            return null;
        }
      })()}
    </div>
  );
}
